/** Full logo as on remocn.dev: R mark (0.76em tall, baseline-aligned) + "emocn" in Manrope 600. */
function RemocnLogo({ fontSize, color }: { fontSize: number; color: string }) {
  return (
    <div
      style={{
        display: "flex",
        alignItems: "baseline",
        color,
        fontFamily: manrope.fontFamily,
        fontWeight: 600,
        fontSize,
        letterSpacing: "-0.025em",
        lineHeight: 1,
      }}
    >
      <svg
        viewBox="0 0 124.06 134.26"
        style={{ height: "0.76em", width: "auto" }}
        aria-hidden
      >
        <path fill="currentColor" d={REMOCN_R_PATH} />
      </svg>
      <span style={{ marginLeft: "0.04em" }}>emocn</span>
    </div>
  );
}

export interface Stat {
  /** The number itself, already formatted: "10,000", "99.9". */
  value: string;
  /** Set small and in the accent, top-aligned after the number: "+", "%", "★". */
  unit?: string;
  /** One or two words beside the number. */
  label: string;
  /** A muted qualifier under the label. */
  detail?: string;
}

export interface StatSequenceProps {
  stats?: Stat[];
  /** Product name in the corner lockup. */
  name?: string;
  /** Muted text after the lockup. */
  eyebrow?: string;
  /** Replaces the default remocn mark in the lockup. */
  logo?: React.ReactNode;
  /** Frames each stat owns before the next one cuts in. */
  beat?: number;
  /** Frames the last stat holds as a hero before the summary row assembles. */
  hold?: number;
  /** Frames between digits as a number rolls in. */
  stagger?: number;
  accent?: string;
  /** Text color, and a solid fill for the numbers in place of the gradient; overrides the theme. */
  ink?: string;
  /** Background fill in place of the theme ground; "transparent" drops it. */
  background?: string;
  /** Typeface for the copy. Load it yourself; Geist by default. */
  fontFamily?: string;
  /** Film grain over the scene. */
  grain?: boolean;
  /** Size of the stats and lockup, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  /** Playback multiplier. */
  speed?: number;
  theme?: "dark" | "light";
}

